<script setup>
import { onMounted, ref } from 'vue'
import { History, X, RefreshCw, ChevronDown } from 'lucide-vue-next'
const props = defineProps({ api: Function, resource: Object })
const emit = defineEmits(['close'])
const items = ref([]), nextBefore = ref(null), busy = ref(false), error = ref('')
const date = value => new Intl.DateTimeFormat('pl-PL', { dateStyle: 'medium', timeStyle: 'medium' }).format(new Date(value))
async function load(more = false) {
  if (busy.value || (more && !nextBefore.value)) return
  busy.value = true; error.value = ''
  try {
    const result = await props.api(`/history/${props.resource.kind}/${encodeURIComponent(props.resource.id)}${more ? `?before=${nextBefore.value}` : ''}`)
    items.value = more ? [...items.value, ...result.items] : result.items; nextBefore.value = result.next_before
  } catch (err) { error.value = err.message } finally { busy.value = false }
}
onMounted(() => load())
</script>
<template>
  <div class="modal-backdrop history-backdrop" @click.self="emit('close')" @keydown.esc="emit('close')"><section class="panel history-dialog" role="dialog" aria-modal="true" aria-labelledby="history-title"><header><span class="history-icon"><History :size="22" /></span><div><h2 id="history-title">Historia zmian</h2><p>{{ resource.title || resource.name || resource.filename }}</p></div><button class="icon-button" :disabled="busy" aria-label="Odśwież historię" @click="load()"><RefreshCw :size="17" /></button><button class="icon-button" aria-label="Zamknij historię" @click="emit('close')"><X :size="20" /></button></header><div class="history-content"><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="busy && !items.length" class="history-empty">Wczytywanie historii…</p><table v-if="items.length"><thead><tr><th scope="col">Data</th><th scope="col">Użytkownik</th><th scope="col">Co zmienił</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td class="history-date">{{ date(item.created_at) }}</td><td>{{ item.actor_name }}</td><td><strong>{{ item.action }}</strong><details v-if="item.changes.length"><summary>{{ item.changes.map(change => change.label).join(', ') }}</summary><div v-for="(change, index) in item.changes" :key="index" class="history-change"><h3>{{ change.label }}</h3><div class="history-values"><div><span>Przed</span><pre>{{ change.before ?? '—' }}</pre></div><div><span>Po</span><pre>{{ change.after ?? '—' }}</pre></div></div></div></details></td></tr></tbody></table><p v-else-if="!busy && !error" class="history-empty">Brak zapisanych zmian. Historia jest rejestrowana od włączenia tej funkcji.</p><button v-if="nextBefore" class="history-more" :disabled="busy" @click="load(true)"><ChevronDown :size="16" /> Starsze wpisy</button></div><footer>Historia zawiera datę, użytkownika i szczegóły zapisanych zmian.</footer></section></div>
</template>
<style scoped>
.history-backdrop { z-index:30; }.history-dialog { width:min(1100px,100%); max-height:90vh; border-radius:20px; display:flex; flex-direction:column; overflow:hidden; }.history-dialog header { display:flex; align-items:center; gap:12px; padding:22px 26px; border-bottom:1px solid var(--border); }.history-icon { display:grid; place-items:center; width:45px; height:45px; background:var(--accent-soft); color:var(--accent); border-radius:12px; flex-shrink:0; }.history-dialog header > div { flex:1; min-width:0; }h2 { font-size:19px; margin:0; }.history-dialog header p { margin:7px 0 0; color:var(--muted); font-size:12px; overflow-wrap:anywhere; }.history-content { padding:12px 24px 24px; overflow:auto; }.history-content table { width:100%; border-collapse:collapse; text-align:left; }.history-content th { padding:14px 12px; font-size:11px; font-weight:500; color:var(--muted); }.history-content td { padding:18px 12px; border-top:1px solid var(--border); font-size:12px; vertical-align:top; }.history-date { color:var(--muted); white-space:nowrap; }.history-content strong { font-weight:500; }.history-content summary { margin-top:8px; color:var(--accent); cursor:pointer; line-height:1.7; }.history-change { padding:12px; margin-top:12px; background:var(--surface-soft); border-radius:10px; }h3 { margin:0 0 10px; font-size:12px; }.history-values { display:grid; grid-template-columns:1fr 1fr; gap:14px; }.history-values span { font-size:10px; color:var(--muted); }.history-values pre { font:inherit; font-size:11px; line-height:1.7; white-space:pre-wrap; overflow-wrap:anywhere; max-height:220px; overflow:auto; }.history-empty { color:var(--muted); padding:25px; font-size:12px; }.history-more { margin:18px auto 0; font-size:12px; }.history-dialog footer { padding:16px 26px; border-top:1px solid var(--border); font-size:11px; color:var(--muted); }@media(max-width:650px) { .history-content { padding:10px; }.history-dialog header { padding:16px; }.history-values { grid-template-columns:1fr; }.history-date { white-space:normal; min-width:100px; } }
</style>
